//! Annotations that carry text, reported beside the Markdown, on the
//! synthetic fixture `tests/fixtures/text_annotations.pdf` (generated by
//! `scripts/make_annotation_fixture.py`, whose docstring lists every
//! annotation in it).

use pdf_inspector::{
    extract_pages_markdown_mem, process_pdf_mem, AnnotationKind, AnnotationRect, PdfAnnotation,
};

const FIXTURE: &str = "tests/fixtures/text_annotations.pdf";

fn fixture() -> Vec<u8> {
    std::fs::read(FIXTURE).expect("annotation fixture")
}

fn rect(x: f32, y: f32, width: f32, height: f32) -> AnnotationRect {
    AnnotationRect {
        x,
        y,
        width,
        height,
    }
}

fn assert_rect_near(actual: AnnotationRect, expected: AnnotationRect) {
    let close = |a: f32, b: f32| (a - b).abs() < 0.01;
    assert!(
        close(actual.x, expected.x)
            && close(actual.y, expected.y)
            && close(actual.width, expected.width)
            && close(actual.height, expected.height),
        "{actual:?} != {expected:?}"
    );
}

/// Page 1's CropBox starts at (36, 36): its geometry is shifted by that.
const CROP: f32 = 36.0;

fn check_fixture_annotations(annotations: &[PdfAnnotation]) {
    let summary: Vec<(u32, AnnotationKind, &str)> = annotations
        .iter()
        .map(|a| (a.page, a.kind, a.text.as_str()))
        .collect();
    assert_eq!(
        summary,
        vec![
            (1, AnnotationKind::Text, "Check the delivery term."),
            (1, AnnotationKind::FreeText, "Draft for review"),
            (
                1,
                AnnotationKind::Highlight,
                "Should this be 30 business days?"
            ),
            (1, AnnotationKind::Text, "Да, рабочих дней."),
            (
                1,
                AnnotationKind::Underline,
                "Due date & penalty\nСрок оплаты"
            ),
            (1, AnnotationKind::StrikeOut, "Delete"),
            (1, AnnotationKind::Squiggly, "Wrong word?"),
            (2, AnnotationKind::Text, "Second page note"),
        ],
        "popups, review states, a markup without a comment and malformed entries are not listed"
    );

    let [note, free_text, highlight, reply, underline, strike, squiggly, second] = annotations
    else {
        unreachable!()
    };

    // The note: /M wins over /CreationDate; a Completed review state resolves it.
    assert_eq!(note.author.as_deref(), Some("Alice"));
    assert_eq!(note.date.as_deref(), Some("D:20261118093000+07'00'"));
    assert!(note.resolved);
    assert_eq!(note.in_reply_to, None);
    assert!(note.quads.is_empty());
    assert_eq!(note.marked_text, None);
    assert_rect_near(note.rect, rect(40.0 - CROP, 694.0 - CROP, 18.0, 18.0));

    assert_eq!(free_text.author.as_deref(), Some("Bob"));
    assert_rect_near(
        free_text.rect,
        rect(360.0 - CROP, 600.0 - CROP, 180.0, 30.0),
    );
    assert_eq!(free_text.marked_text, None);
    assert!(!free_text.resolved);

    // The highlight: /CreationDate when there is no /M; one quad, which is
    // also its rectangle; the words under it.
    assert_eq!(highlight.author.as_deref(), Some("Alice"));
    assert_eq!(highlight.date.as_deref(), Some("D:20261118091500Z"));
    assert_eq!(highlight.quads.len(), 1);
    assert_rect_near(highlight.quads[0], highlight.rect);
    assert!((highlight.rect.y - (697.0 - CROP)).abs() < 0.01);
    assert!((highlight.rect.height - 13.0).abs() < 0.01);
    assert_eq!(highlight.marked_text.as_deref(), Some("thirty days"));
    assert!(!highlight.resolved);

    // The reply, in Russian, points at the highlight.
    assert_eq!(reply.author.as_deref(), Some("Борис"));
    assert_eq!(reply.date.as_deref(), Some("D:20261118100000+03'00'"));
    assert_eq!(reply.in_reply_to, Some(2));
    assert_eq!(reply.marked_text, None);

    // Rich text only: reduced to plain text.
    assert_eq!(underline.author.as_deref(), Some("Ирина"));
    assert_eq!(underline.marked_text.as_deref(), Some("Payment is due"));
    assert_eq!(strike.marked_text.as_deref(), Some("shall"));
    assert_eq!(squiggly.marked_text.as_deref(), Some("invoice"));

    // Page 2 has no CropBox; its latest review state is Rejected.
    assert_rect_near(second.rect, rect(40.0, 694.0, 18.0, 18.0));
    assert!(!second.resolved);
    assert_eq!(second.author.as_deref(), Some("Bob"));
}

#[test]
fn per_page_extraction_reports_the_fixture_annotations() {
    let result = extract_pages_markdown_mem(&fixture(), None).expect("extract");
    check_fixture_annotations(&result.annotations);
}

#[test]
fn requested_pages_limit_the_annotations() {
    let result = extract_pages_markdown_mem(&fixture(), Some(&[1])).expect("extract");
    assert_eq!(result.annotations.len(), 1);
    assert_eq!(result.annotations[0].text, "Second page note");
    assert_eq!(result.annotations[0].page, 2);

    // Request order decides the list order; reply indices follow it.
    let result = extract_pages_markdown_mem(&fixture(), Some(&[1, 0])).expect("extract");
    assert_eq!(result.annotations[0].page, 2);
    let reply = result
        .annotations
        .iter()
        .find(|a| a.text == "Да, рабочих дней.")
        .unwrap();
    let parent = &result.annotations[reply.in_reply_to.unwrap()];
    assert_eq!(parent.kind, AnnotationKind::Highlight);
}

#[test]
fn annotation_text_stays_out_of_the_markdown() {
    let bytes = fixture();
    let process = process_pdf_mem(&bytes)
        .unwrap()
        .markdown
        .unwrap_or_default();
    let pages: String = extract_pages_markdown_mem(&bytes, None)
        .unwrap()
        .pages
        .into_iter()
        .map(|page| page.markdown)
        .collect();
    for markdown in [&process, &pages] {
        assert!(markdown.contains("thirty days"), "{markdown}");
        assert!(markdown.contains("Second page with a note"), "{markdown}");
        for annotation_text in [
            "Check the delivery",
            "Draft for review",
            "Should this be",
            "рабочих",
            "Due date",
            "Срок",
            "Delete",
            "Wrong word",
            "Second page note",
            "Alice",
        ] {
            assert!(
                !markdown.contains(annotation_text),
                "{annotation_text:?} reached the Markdown:\n{markdown}"
            );
        }
    }
}

#[test]
fn a_pdf_without_annotations_reports_none() {
    let bytes = std::fs::read("tests/fixtures/cropbox_offset_origin.pdf").unwrap();
    let result = extract_pages_markdown_mem(&bytes, None).unwrap();
    assert!(result.annotations.is_empty());
}

#[cfg(feature = "ocr")]
#[test]
fn the_ocr_pipeline_reports_the_native_annotations() {
    use pdf_inspector::vision::{process_pdf_with_ocr_mem, OcrPdfOptions};
    let result = process_pdf_with_ocr_mem(&fixture(), OcrPdfOptions::new()).expect("native pass");
    check_fixture_annotations(&result.annotations);
}
